def comb_sort(arr):
  gap = len(arr)
  shrink_factor = 1.3
  while gap > 1:
    gap = int(gap / shrink_factor)
    for i in range(len(arr) - gap):
      j = i + gap
      if arr[i] > arr[j]:
        arr[i], arr[j] = arr[j], arr[i]
  return arr

